function App() {
  const [Comp, setComp] = useState(null);
  const [loading, setLoading] = useState(false);
  const load = () => {
    setLoading(true);
    // Simulate async chunk download (like next/dynamic import())
    setTimeout(() => {
      setComp(() => () => <div style={{ padding: 12, background: '#ecfdf5', borderRadius: 8 }}>Heavy chart loaded on demand</div>);
      setLoading(false);
    }, 700);
  };
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <h3>Lazy-loaded widget</h3>
      {!Comp && <button onClick={load} disabled={loading}>{loading ? 'Loading chunk…' : 'Load chart'}</button>}
      {Comp && <Comp />}
    </div>
  );
}

