// Page stays a Server Component. Only FilterControls is 'use client'.
// Chart is dynamic-imported (ssr:false) so its JS is deferred.
function FilterControls() { // 'use client' in its own file
  const [filter, setFilter] = useState('all');
  return <button onClick={() => setFilter(f => f === 'all' ? 'active' : 'all')}>Filter: {filter}</button>;
}
function App() {
  // Server Component: static markup + server data, no JS shipped here
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <h2>Dashboard (server-rendered)</h2>
      <FilterControls />
      <p>Static content ships as HTML; the heavy chart loads via next/dynamic.</p>
    </div>
  );
}

// app/page.tsx (Server Component)
import Image from 'next/image';
import dynamic from 'next/dynamic';
import hero from '@/public/hero.jpg';

// Heavy, browser-only widget — deferred out of the initial bundle
const Chart = dynamic(() => import('@/components/Chart'), {
  ssr: false,
  loading: () => <p>Loading chart…</p>,
});

export default function Page() {
  return (
    <main>
      <Image src={hero} alt="Product hero" priority sizes="100vw" />
      <Chart />
    </main>
  );
}
